; Auto-generated by scripts/generate-palette-transitions.js from src/games/tg-tetris/palettes/.
; Do not edit by hand -- regenerate instead.
;
; Every palette has one fixed IIgs slot layout: the IIgs palette 0 slot that each of the 32 NES
; palette RAM entries ($3F00-$3F1F) is shown in.  The layouts are chosen together, so that the
; background groups that keep the same slots across the transitions don't need their tiles
; redrawn (a group whose slots change has to be recompiled with the new swizzle table).
;
; Requires: NES_ColorToIIgs_X, NES_SetPaletteMap, RefreshPPUAttributesL, PPU_SetPaletteWritesL,
;           ppuPalDirty, _ppumask, PPU_MEM, SHR_PALETTES

; Swizzle tables, in the PALDATA segment (palettes.s)
PAL_TITLE_SWIZZLE EXT
PAL_MENU_SWIZZLE EXT
PAL_GAME_1P_SWIZZLE EXT
PAL_GAME_2P_SWIZZLE EXT
PAL_LEADERBOARD_SWIZZLE EXT
PAL_BONUS_SWIZZLE EXT

; The palette ids (PAL_*) and pinned slots (PAL_SLOT_*) are in pal_defs.s.

; Layouts (NES color -> [slots] per group; *reserved, ~shown as):
;   title
;     BG0 $0F $31 $21 $11 -> [0,1,2,3]
;     BG1 $0F $26 $16 $06 -> [0,4,5,6]
;     BG2 $0F $37 $27 $17 -> [0,7,8,9]
;     BG3 $0F $2A $1A $0A -> [0,10,11,12]
;     SP0 $0F $37 $27 $06 -> [0,7,8,6]
;     SP1 $0F $31 $06 $11 -> [0,1,6,3]
;     SP2 $0F $17 $21 $26 -> [0,9,2,4]
;     SP3 $0F $26 $16 $06 -> [0,4,5,6]
;   menu
;     BG0 $0F $12 $0F $0F -> [0,1,2,3]
;     BG1 $0F $27 $0F $0F -> [0,4,5,6]
;     BG2 $0F $31 $21 $01 -> [0,7,8,9]
;     BG3 $0F $30 $16 $00 -> [0,10,11,12]
;     SP0 $0F $16 $0F $00 -> [0,11,0,12]
;     SP1 $0F $12 $24 $1B -> [0,1,13,14]
;     SP2 $0F $0F $0F $0F -> [0,0,0,0]
;     SP3 $0F $37 $0F $0F -> [0,15,0,0]
;   game_1p
;     BG0 $0F *$20 *$10 *$00 -> [0,1,2,3]
;     BG1 $0F $27~$16 $18~$16 $08~$00 -> [0,11,11,12]
;     BG2 $0F $31 $21 $01 -> [0,7,8,9]
;     BG3 $0F $30 $16 $00 -> [0,10,11,12]
;     SP0 $0F *$16 *$0F *$00 -> [0,4,5,6]
;     SP1 $0F $12~$21 $24~$21 $1B~$21 -> [0,8,8,8]
;     SP2 $0F *$0F *$0F *$0F -> [0,13,14,15]
;     SP3 $0F -- -- -- -> [0,0,0,0]
;   game_2p
;     BG0 $0F *$20 *$10 *$00 -> [0,1,2,3]
;     BG1 $0F *$27 *$18 *$08 -> [0,4,5,6]
;     BG2 $0F $31~$30 $21 $01~$21 -> [0,10,12,12]
;     BG3 $0F $30 $16 $00~$21 -> [0,10,11,12]
;     SP0 $0F *$16 *$0F *$00 -> [0,7,8,9]
;     SP1 $0F *$12 *$24 *$1B -> [0,13,14,15]
;     SP2 $0F -- -- -- -> [0,0,0,0]
;     SP3 $0F -- -- -- -> [0,0,0,0]
;   leaderboard
;     BG0 $0F $12 $0F $0F -> [0,1,0,0]
;     BG1 $0F $27 $0F $0F -> [0,2,0,0]
;     BG2 $0F $31 $21 $01 -> [0,7,8,9]
;     BG3 $0F $30 $16 $00 -> [0,10,11,12]
;     SP0 $0F $37 $39 $3B~$31 -> [0,3,4,7]
;     SP1 $0F $2A $2B~$2A $30 -> [0,5,5,10]
;     SP2 $0F $26 $21 $37 -> [0,6,8,3]
;     SP3 $0F $35 $24 $13 -> [0,13,14,15]
;   bonus
;     BG0 $0F $30 $16 $0F -> [0,10,11,0]
;     BG1 $0F *$30 *$16 *$0F -> [0,4,5,6]
;     BG2 $0F $31 $21 $01 -> [0,7,8,9]
;     BG3 $0F $30 $16 $00 -> [0,10,11,12]
;     SP0 $0F $35 $16 $12 -> [0,1,11,2]
;     SP1 $0F -- -- -- -> [0,0,0,0]
;     SP2 $0F $35 $1A $37 -> [0,1,3,13]
;     SP3 $0F $35 $18 $24 -> [0,1,14,15]

            mx    %00

palCurrent  dw    0                   ; PAL_* id of the palette on screen (0 = none yet)

; SetDefaultPalette
;
; Before the game uploads a palette: the swizzle tables are title's, and so is the layout of the colors
; shown until the game's palette is detected.
; Called by the game's InitPlayfield (NES_StartUp) and at start-up.
SetDefaultPalette
            ldy   #PAL_TITLE
            sty   palCurrent
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jmp   NES_SetPaletteMap

; ApplyPaletteChange
;
; The game's PRE_RENDER hook (jsl), on the GS task.  If the palette RAM changed (ppuPalDirty, set by the
; engine's palette write handler), identify the palette in it and switch to it, or show its changed
; colors in the current palette's layout (fades, color cycling, an unknown palette).  While the
; background is off, the game is rebuilding the screen: the old colors stay on whatever is left on it,
; and the new ones come with the new screen.
ApplyPaletteChange
            ldal  ppuPalDirty
            beq   :none
            ldal  _ppumask
            and   #NES_PPUMASK_BG
            beq   :none
            lda   #0
            stal  ppuPalDirty         ; (first, so a write from here on is seen next time)
            ldx   palCurrent
            jsr   DetectNESPalette    ; A = Y = palette id, 0 if none
            beq   :colors             ; not a known palette (e.g. a step of a fade)
            cmp   palCurrent
            beq   :colors
            ldx   palCurrent
            sty   palCurrent
            jsr   UpdatePalette       ; X = from, Y = to
            rtl
:colors     ldy   palCurrent
            beq   :none               ; no palette yet
            jsr   LoadPaletteColors
:none       rtl

; UpdatePalette
;
; X = from palette id (PAL_*, or 0 for none), Y = to palette id
;
; Switches the swizzle tables to the new palette, loads its colors (LoadPaletteColors), then redraws
; the background groups whose slots changed.  Call from the GS task (it redraws tiles).
UpdatePalette
            lda   BG_UPDATE_MASKS,x
            pha
            lda   (1,s),y
            sta   1,s                 ; 1,s = groups to redraw

            phy
            ldx   PAL_SWIZZLE_LO,y
            lda   PAL_SWIZZLE_HI,y
            jsr   NES_SetPaletteMap
            ply

            jsr   LoadPaletteColors
            pla
            jsl   RefreshPPUAttributesL   ; (in the engine bank: ppu_entry.s)
            rts

; LoadPaletteColors
;
; Y = palette id.  Loads IIgs palette 0 from the current NES palette RAM, in the palette's layout,
; so the colors the game changes on the fly (fades, color cycling, ...) are shown too.  Slot 0 (the
; universal background color) is left alone: the game's $3F00 writes set it directly.
LoadPaletteColors
            lda   PAL_CELLS,y
            pha                       ; 1,s = slot map
            ldy   #31                 ; Backwards, so the BG colors win a shared slot
:loop       lda   (1,s),y
            and   #$00FF
            cmp   #$00FF
            beq   :next               ; not shown
            pha                       ; 1,s = slot * 2
            tyx
            ldal  PPU_MEM+$3F00,x
            jsr   NES_ColorToIIgs_X
            plx
            stal  SHR_PALETTES,x
:next       dey
            bpl   :loop
            pla
            rts

; DetectNESPalette
;
; X = the current palette id (0 = none).  Returns A = Y = the PAL_* id of the palette whose
; colors 1-3 are all in palette RAM (other than the reserved ones), or 0 if there is none (e.g. a
; step of a fade).  The current palette is tried first,
; then the palettes that follow it in the transitions, then the rest.
DetectNESPalette
            php
            rep   #$30
            stx   :from
            txa
            beq   :all
            jsr   :match              ; still the current palette?
            bcs   :found
            ldx   :from
            lda   PAL_SUCC,x          ; its successors, a 0-terminated list of ids
:snext      sta   :ptr
            tax
            lda:  0,x
            beq   :all
            tax
            jsr   :match
            bcs   :found
            lda   :ptr
            inc
            inc
            bra   :snext
:all        ldx   #2
:anext      jsr   :match
            bcs   :found
            inx
            inx
            cpx   #14
            bcc   :anext
            ldx   #0
:found      txy
            plp
            tya
            rts

; X = palette id.  Carry set if its colors are in palette RAM.  X is kept.  Only colors 1-3 of
; each group are compared (24 at most): color 0 is always IIgs slot 0.  One pass per group, from
; SP3 back to BG0, with its three colors compared inline.  NES colors are $00-$3F, so the $FF of a
; reserved or unused color is the only table byte with bit 7 set, and bmi skips it.
:match      phx
            lda   PAL_MATCH,x
            clc
            adc   #21
            tay                       ; Y -> the last group's 3 bytes
            ldx   #28                 ; X = the last group's palette RAM offset
            sep   #$20
            mx    %10
:group      lda:  0,y                 ; color 1
            bmi   *+8                 ; $FF = any value
            cmpl  PPU_MEM+$3F01,x
            bne   :mfail
            lda:  1,y                 ; color 2
            bmi   *+8
            cmpl  PPU_MEM+$3F02,x
            bne   :mfail
            lda:  2,y                 ; color 3
            bmi   *+8
            cmpl  PPU_MEM+$3F03,x
            bne   :mfail
            dey
            dey
            dey
            dex
            dex
            dex
            dex
            bpl   :group
            rep   #$20
            mx    %00
            plx
            sec
            rts
:mfail      rep   #$20
            plx
            clc
            rts

:from       ds    2
:ptr        ds    2

; id -> colors 1-3 of each group to match (BG0-BG3, SP0-SP3; $FF = any value: reserved or unused)
PAL_MATCH
            dw    0
            dw    PAL_TITLE_MATCH
            dw    PAL_MENU_MATCH
            dw    PAL_GAME_1P_MATCH
            dw    PAL_GAME_2P_MATCH
            dw    PAL_LEADERBOARD_MATCH
            dw    PAL_BONUS_MATCH
PAL_TITLE_MATCH
            db    $31,$21,$11,$26,$16,$06,$37,$27,$17,$2A,$1A,$0A   ; BG0-BG3
            db    $37,$27,$06,$31,$06,$11,$17,$21,$26,$26,$16,$06   ; SP0-SP3
PAL_MENU_MATCH
            db    $12,$0F,$0F,$27,$0F,$0F,$31,$21,$01,$30,$16,$00   ; BG0-BG3
            db    $16,$0F,$00,$12,$24,$1B,$0F,$0F,$0F,$37,$0F,$0F   ; SP0-SP3
PAL_GAME_1P_MATCH
            db    $FF,$FF,$FF,$27,$18,$08,$31,$21,$01,$30,$16,$00   ; BG0-BG3
            db    $FF,$FF,$FF,$12,$24,$1B,$FF,$FF,$FF,$FF,$FF,$FF   ; SP0-SP3
PAL_GAME_2P_MATCH
            db    $FF,$FF,$FF,$FF,$FF,$FF,$31,$21,$01,$30,$16,$00   ; BG0-BG3
            db    $FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF   ; SP0-SP3
PAL_LEADERBOARD_MATCH
            db    $12,$0F,$0F,$27,$0F,$0F,$31,$21,$01,$30,$16,$00   ; BG0-BG3
            db    $37,$39,$3B,$2A,$2B,$30,$26,$21,$37,$35,$24,$13   ; SP0-SP3
PAL_BONUS_MATCH
            db    $30,$16,$0F,$FF,$FF,$FF,$31,$21,$01,$30,$16,$00   ; BG0-BG3
            db    $35,$16,$12,$FF,$FF,$FF,$35,$1A,$37,$35,$18,$24   ; SP0-SP3

; id -> the ids of the palettes that can follow it (transitions), 0-terminated
PAL_SUCC
            dw    PAL_NONE_SUCC
            dw    PAL_TITLE_SUCC
            dw    PAL_MENU_SUCC
            dw    PAL_GAME_1P_SUCC
            dw    PAL_GAME_2P_SUCC
            dw    PAL_LEADERBOARD_SUCC
            dw    PAL_BONUS_SUCC
PAL_NONE_SUCC
            dw    0
PAL_TITLE_SUCC
            dw    PAL_MENU,PAL_GAME_1P,PAL_GAME_2P,PAL_LEADERBOARD,0
PAL_MENU_SUCC
            dw    PAL_TITLE,PAL_GAME_1P,PAL_GAME_2P,0
PAL_GAME_1P_SUCC
            dw    PAL_BONUS,PAL_LEADERBOARD,PAL_TITLE,PAL_MENU,PAL_GAME_2P,0
PAL_GAME_2P_SUCC
            dw    PAL_BONUS,PAL_LEADERBOARD,PAL_TITLE,PAL_MENU,PAL_GAME_1P,0
PAL_LEADERBOARD_SUCC
            dw    PAL_TITLE,PAL_MENU,0
PAL_BONUS_SUCC
            dw    PAL_GAME_1P,PAL_GAME_2P,PAL_LEADERBOARD,PAL_TITLE,0

; id -> swizzle tables (PALDATA segment, palettes.s)
PAL_SWIZZLE_LO
            dw    0
            dw    PAL_TITLE_SWIZZLE
            dw    PAL_MENU_SWIZZLE
            dw    PAL_GAME_1P_SWIZZLE
            dw    PAL_GAME_2P_SWIZZLE
            dw    PAL_LEADERBOARD_SWIZZLE
            dw    PAL_BONUS_SWIZZLE
PAL_SWIZZLE_HI
            dw    0
            dw    ^PAL_TITLE_SWIZZLE
            dw    ^PAL_MENU_SWIZZLE
            dw    ^PAL_GAME_1P_SWIZZLE
            dw    ^PAL_GAME_2P_SWIZZLE
            dw    ^PAL_LEADERBOARD_SWIZZLE
            dw    ^PAL_BONUS_SWIZZLE

; id -> slot map: for each NES palette RAM entry, the IIgs slot * 2, or $FF if it isn't loaded
; (color 0, which the game writes straight to slot 0, colors that share slot 0 with it, and
; approximated colors, which are shown in another color's slot)
PAL_CELLS
            dw    0
            dw    PAL_TITLE_CELLS
            dw    PAL_MENU_CELLS
            dw    PAL_GAME_1P_CELLS
            dw    PAL_GAME_2P_CELLS
            dw    PAL_LEADERBOARD_CELLS
            dw    PAL_BONUS_CELLS
PAL_TITLE_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$14,$16,$18   ; BG0-BG3
            db    $FF,$0E,$10,$0C,$FF,$02,$0C,$06,$FF,$12,$04,$08,$FF,$08,$0A,$0C   ; SP0-SP3
PAL_MENU_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$14,$16,$18   ; BG0-BG3
            db    $FF,$16,$FF,$18,$FF,$02,$1A,$1C,$FF,$FF,$FF,$FF,$FF,$1E,$FF,$FF   ; SP0-SP3
PAL_GAME_1P_CELLS
            db    $FF,$02,$04,$06,$FF,$FF,$FF,$FF,$FF,$0E,$10,$12,$FF,$14,$16,$18   ; BG0-BG3
            db    $FF,$08,$0A,$0C,$FF,$FF,$FF,$FF,$FF,$1A,$1C,$1E,$FF,$FF,$FF,$FF   ; SP0-SP3
PAL_GAME_2P_CELLS
            db    $FF,$02,$04,$06,$FF,$08,$0A,$0C,$FF,$FF,$18,$FF,$FF,$14,$16,$FF   ; BG0-BG3
            db    $FF,$0E,$10,$12,$FF,$1A,$1C,$1E,$FF,$FF,$FF,$FF,$FF,$FF,$FF,$FF   ; SP0-SP3
PAL_LEADERBOARD_CELLS
            db    $FF,$02,$FF,$FF,$FF,$04,$FF,$FF,$FF,$0E,$10,$12,$FF,$14,$16,$18   ; BG0-BG3
            db    $FF,$06,$08,$FF,$FF,$0A,$FF,$14,$FF,$0C,$10,$06,$FF,$1A,$1C,$1E   ; SP0-SP3
PAL_BONUS_CELLS
            db    $FF,$14,$16,$FF,$FF,$08,$0A,$0C,$FF,$0E,$10,$12,$FF,$14,$16,$18   ; BG0-BG3
            db    $FF,$02,$16,$04,$FF,$FF,$FF,$FF,$FF,$02,$06,$1A,$FF,$02,$1C,$1E   ; SP0-SP3

; from id -> its row of to id -> background groups to redraw (bit 0 = BG0 .. bit 3 = BG3).
; From no palette (0), everything is redrawn.
BG_UPDATE_MASKS
            dw    BG_UPDATE_MASKS_NONE
            dw    BG_UPDATE_MASKS_TITLE
            dw    BG_UPDATE_MASKS_MENU
            dw    BG_UPDATE_MASKS_GAME_1P
            dw    BG_UPDATE_MASKS_GAME_2P
            dw    BG_UPDATE_MASKS_LEADERBOARD
            dw    BG_UPDATE_MASKS_BONUS
BG_UPDATE_MASKS_NONE
            dw    $0000,%1111,%1111,%1111,%1111,%1111,%1111
BG_UPDATE_MASKS_TITLE
            dw    $0000
            dw    %0000   ; to title
            dw    %0000   ; to menu
            dw    %0010   ; to game_1p
            dw    %0100   ; to game_2p
            dw    %0011   ; to leaderboard
            dw    %0001   ; to bonus
BG_UPDATE_MASKS_MENU
            dw    $0000
            dw    %0000   ; to title
            dw    %0000   ; to menu
            dw    %0010   ; to game_1p
            dw    %0100   ; to game_2p
            dw    %0011   ; to leaderboard
            dw    %0001   ; to bonus
BG_UPDATE_MASKS_GAME_1P
            dw    $0000
            dw    %0010   ; to title
            dw    %0010   ; to menu
            dw    %0000   ; to game_1p
            dw    %0110   ; to game_2p
            dw    %0011   ; to leaderboard
            dw    %0011   ; to bonus
BG_UPDATE_MASKS_GAME_2P
            dw    $0000
            dw    %0100   ; to title
            dw    %0100   ; to menu
            dw    %0110   ; to game_1p
            dw    %0000   ; to game_2p
            dw    %0111   ; to leaderboard
            dw    %0101   ; to bonus
BG_UPDATE_MASKS_LEADERBOARD
            dw    $0000
            dw    %0011   ; to title
            dw    %0011   ; to menu
            dw    %0011   ; to game_1p
            dw    %0111   ; to game_2p
            dw    %0000   ; to leaderboard
            dw    %0011   ; to bonus
BG_UPDATE_MASKS_BONUS
            dw    $0000
            dw    %0001   ; to title
            dw    %0001   ; to menu
            dw    %0011   ; to game_1p
            dw    %0101   ; to game_2p
            dw    %0011   ; to leaderboard
            dw    %0000   ; to bonus
